import json
d = json.load(open('/home/ubuntu/.agent-ml-research-prod_0510/projects/causal_annot_error_attrib/artifacts/plan006/asv_empirical_results.json'))

# Extract all f1_vs_bias entries
entries = d['f1_vs_bias']
print(f'Total entries: {len(entries)}')

# Per-config F1 values
configs = {}
for e in entries:
    key = f\"{e['model']}/{e['prompt']}\"
    if key not in configs:
        configs[key] = e['macro_f1']

print('\n=== Per-Config Macro F1 ===')
for k in sorted(configs):
    print(f'  {k}: {configs[k]:.10f}')

# Per-config × topology bias_pct
print('\n=== All 63 data points (model/prompt, topology, F1, bias_pct) ===')
for e in sorted(entries, key=lambda x: (x['model'], x['prompt'], x['topology'])):
    print(f\"{e['model']}/{e['prompt']:12s} | {e['topology']:12s} | F1={e['macro_f1']:.4f} | bias_pct={e['bias_pct']:.6f} | sign_flip={e['sign_flip']}\")

# Check ASV unsafe
asvs = [a for a in d['asvs'] if a.get('dataset') == 'humaid']
print(f'\n=== ASV entries for humaid: {len(asvs)} ===')
unsafe_by_topo = {}
for a in asvs:
    topo = a.get('topology', '')
    unsafe = a.get('asv_unsafe', a.get('unsafe', None))
    if topo not in unsafe_by_topo:
        unsafe_by_topo[topo] = {'total': 0, 'unsafe': 0}
    unsafe_by_topo[topo]['total'] += 1
    if unsafe:
        unsafe_by_topo[topo]['unsafe'] += 1

for topo in sorted(unsafe_by_topo):
    d2 = unsafe_by_topo[topo]
    print(f'  {topo}: {d2[\"unsafe\"]}/{d2[\"total\"]} unsafe ({d2[\"unsafe\"]/d2[\"total\"]*100:.1f}%)')
